package com.lucent.app.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.Base64

class DocTextExtractorTest {

    private val FIXTURE_DOC =
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////8="

    private fun fixtureBytes(): ByteArray = Base64.getDecoder().decode(FIXTURE_DOC)

    @Test
    fun docWithUnicodePiecesYieldsExactText() {
        assertEquals(SAMPLE_TEXT, DocTextExtractor.extract(fixtureBytes()))
    }

    @Test
    fun parserExposesDocAsSupportedExtension() {
        assertTrue(MarkdownDocumentParser.isSupported("旧文档.doc"))
        assertEquals(SAMPLE_TEXT, MarkdownDocumentParser.parseDocToMarkdown(fixtureBytes()))
    }

    @Test
    fun zeroFilledFileIsRejectedNotCrashed() {
        val failure = runCatching { DocTextExtractor.extract(ByteArray(8192)) }.exceptionOrNull()
        assertTrue("垃圾输入必须被拒绝", failure != null)
    }

    @Test
    fun docxArchiveIsRejectedByTheDocReader() {
        val zip = ByteArray(6000)
        val magic = "PK".toByteArray(Charsets.US_ASCII)
        zip[0] = magic[0]
        zip[1] = magic[1]
        val failure = runCatching { DocTextExtractor.extract(zip) }.exceptionOrNull()
        assertTrue("DOCX 不能被当成 DOC 解析", failure != null)
    }

    companion object {
        private const val SAMPLE_TEXT = "第一章 拥抱\n她终于明白，有些事情只能自己走完。"
    }
}
